const languages={'ar-EG':{name:'Egyptian Arabic',native:'مصري',rtl:true},ru:{name:'Russian',native:'Русский'},he:{name:'Hebrew',native:'עברית',rtl:true},fr:{name:'French',native:'Français'},es:{name:'Spanish',native:'Español'}};
const form=document.querySelector('#translation-form'),controls=document.querySelector('#translation-controls'),text=document.querySelector('#source-words'),button=document.querySelector('#translate-button'),status=document.querySelector('#translation-status'),retry=document.querySelector('#translation-retry'),login=document.querySelector('#translation-login'),results=document.querySelector('.translation-results'),cards=document.querySelector('#translation-card-list'),context=document.querySelector('#results-context'),copyStatus=document.querySelector('#copy-status');
let ready=false,busy=false;
function message(value,error=false){status.textContent=value;status.dataset.error=String(error);}
function updateButton(){button.disabled=!ready || busy || !text.value.trim() || !form.querySelector('input[name=target]:checked');document.querySelector('#words-count').textContent=`${text.value.length.toLocaleString()} / 1,500`;}
form.addEventListener('input',updateButton);form.addEventListener('change',updateButton);
async function api(method='GET',body){let response;try{response=await fetch('/api/translation',{method,credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(method==='POST'?55000:15000),headers:{Accept:'application/json',...(body?{'Content-Type':'application/json','X-Asechka-Translation':'1'}:{})},...(body?{body:JSON.stringify(body)}:{})});}catch{throw new Error('Our connection needs a little moment. Your words are still here—try again.');}let data;try{data=await response.json();}catch{throw new Error('The translator couldn’t be reached. Your words are still here.');}if(!response.ok){const error=new Error(data.error || 'Try again in a little moment.');error.status=response.status;throw error;}return data;}
async function checkConnection(){retry.hidden=true;message('Opening our little phrasebook…');try{const data=await api();ready=data.ready;message(ready?'A little thought. A natural way to say it.':'Our natural translator is being connected. Your words can wait right here.');retry.hidden=ready;login.hidden=true;}catch(error){ready=false;message(error.message,true);retry.hidden=error.status===401;login.hidden=error.status!==401;}updateButton();}
retry.addEventListener('click',checkConnection);
function element(tag,className,value){const node=document.createElement(tag);if(className)node.className=className;if(value!==undefined)node.textContent=value;return node;}
function render(translations,input){cards.replaceChildren();copyStatus.textContent='';document.querySelector('#translation-empty').hidden=true;context.hidden=false;context.textContent=`${translations.length} ${translations.length===1?'language':'languages'} · ${input.tone==='natural'?'Natural & everyday':input.tone==='sweet'?'A little sweeter':'Soft & poetic'} · Same meaning, in your chosen words.`;
  for(const item of translations){const language=languages[item.language];if(!language)continue;const card=element('article','translation-card'),heading=element('div','translation-card-heading'),title=element('h3','',language.name),native=element('span','',language.native);native.lang=item.language;title.append(native);const copy=element('button','copy-translation','Copy ↗');copy.type='button';copy.setAttribute('aria-label',`Copy ${language.name} translation`);const words=element('p','translated-text',item.text);words.lang=item.language;words.dir=language.rtl?'rtl':'ltr';copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(item.text);copyStatus.textContent=`${language.name} copied. Ready for a little message. ♡`;}catch{copyStatus.textContent='Select the words above, then copy them to your message.';}});heading.append(title,copy);card.append(heading,words);const details=element('details'),summary=element('summary','','Pronunciation & meaning');details.append(summary);for(const [field,label] of [['pronunciation','How it sounds'],['backTranslation','The meaning in English'],['note','A little language note']]){if(!item[field])continue;const detail=element('p','translation-detail'),caption=element('b','',label);detail.append(caption,document.createTextNode(item[field]));details.append(detail);}card.append(details);cards.append(card);}
}
form.addEventListener('submit',async event=>{event.preventDefault();if(busy || !ready)return;const values=new FormData(form),input={text:String(values.get('text') || ''),source:values.get('source'),targets:values.getAll('target'),tone:values.get('tone'),speaker:values.get('speaker'),recipient:values.get('recipient')};if(!input.text.trim() || !input.targets.length){message('Write a little message and choose at least one language.',true);return;}busy=true;controls.disabled=true;results.setAttribute('aria-busy','true');button.textContent='Finding the right words…';updateButton();message('Giving your words a little care…');try{const data=await api('POST',input);render(data.translations,input);message('Same thought, a few new ways to say it. ♡');login.hidden=true;}catch(error){message(error.message,true);login.hidden=error.status!==401;if(error.status===401){ready=false;retry.hidden=true;}}finally{busy=false;controls.disabled=false;results.setAttribute('aria-busy','false');button.textContent='Translate our words ↗';updateButton();}});
checkConnection();
